(function(){

	var init = function(){
		if($('.tabs').length){
			tabsSec();
		}

		if($('#up').length){
			scrollTop();
		}

		scrollNav();
	};

	var tabsSec = function(){
		var tabs = $('.tabs'),
			tabNav = tabs.find('.tabs-nav'),
			tabCont,
			index;

		tabNav.on('click', 'a', function(e){
			e.preventDefault();

			var that = $(this);

			that.parents('.tabs-nav').find('.active').removeClass('active');
			that.addClass('active');

			index = that.parent().index();

			tabCont = that.parents('.tabs').find('.tab-content > li');

			// detener animaciones y ocultar todo inmediatamente
			tabCont.stop(true, true).hide();

			// mostrar solo el seleccionado
			tabCont.eq(index).fadeIn('fast');
		});
	};

	var scrollTop = function(){
		var btn = $('#up');

		btn.on('click', function(e){
			e.preventDefault();
			$("html, body").animate({ scrollTop: 0 }, 600);
		});
	};

	var scrollNav = function(){
		var nav = $('nav'),
			divSec;

		nav.on('click', 'a', function(e){
			e.preventDefault();
			var that = $(this);
			divSec = that.attr('href');

			$('html, body').animate({scrollTop:$(divSec).position().top}, 600);

			//alert(divSec);
		});
	};

	init();

})();